95	     * a space, and the national digits grouped in threes separated by spaces, e.g.
96	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}. The raw {@code telephone} is
97	     * left unchanged in E.164 form.
98	     */
99	    default String telephoneDisplay(Owner owner) {
100	        if (owner == null) {
101	            return null;
