106	    /**
107	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
108	     * code, the literal {@code '-M'}, and the last two digits of the registrationDate year.
109	     * Returns {@code null} unless both the customer code and registration date are present.
110	     */
111	    default String membershipNumber(Owner owner) {
112	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
113	            return null;
114	        }
115	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
116	        return owner.getCustomerCode() + "-M" + yy;
117	    }
