119	    /**
120	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
121	     * contained in the {@code customerCode}. Returns {@code null} when no customer code is present.
122	     */
123	    default Integer checkDigit(Owner owner) {
124	        if (owner == null || owner.getCustomerCode() == null) {
125	            return null;
126	        }
127	        String code = owner.getCustomerCode();
128	        int sum = 0;
129	        boolean dbl = true;
130	        for (int i = code.length() - 1; i >= 0; i--) {
131	            char c = code.charAt(i);
132	            if (c < '0' || c > '9') {
133	                continue;
134	            }
135	            int d = c - '0';
136	            if (dbl) {
137	                d *= 2;
138	                if (d > 9) {
139	                    d -= 9;
140	                }
141	            }
142	            sum += d;
143	            dbl = !dbl;
144	        }
145	        return (10 - (sum % 10)) % 10;
146	    }
