150	     * address is present; adds {@code 1} when the owner has no namesakes (namesakeCount is 0);
151	     * adds {@code 2} when the owner belongs to a household of {@code 3} or more members; adds
152	     * {@code 3} when the owner's tenure exceeds 365 days.
153	     */
154	    default Integer membershipPoints(Owner owner) {
155	        if (owner == null) {
156	            return null;
157	        }
158	        int points = 0;
159	        String email = owner.getEmail();
160	        if (email != null && !email.isEmpty()) {
161	            points += 2;
162	        }
163	        Integer namesakeCount = owner.getNamesakeCount();
164	        if (namesakeCount != null && namesakeCount == 0) {
165	            points += 1;
166	        }
167	        Integer householdMemberCount = owner.getHouseholdMemberCount();
168	        if (householdMemberCount != null && householdMemberCount >= 3) {
169	            points += 2;
170	        }
171	        LocalDate registrationDate = owner.getRegistrationDate();
172	        if (registrationDate != null
173	                && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
174	            points += 3;
175	        }
176	        return points;
177	    }
