181	     * {@code 1} for {@code 0-1} points, level {@code 2} for {@code 2-3} points, level {@code 3}
182	     * for {@code 4-5} points, and level {@code 4} for {@code 6} or more points.
183	     */
184	    default Integer membershipLevel(Owner owner) {
185	        if (owner == null) {
186	            return null;
187	        }
188	        int points = membershipPoints(owner);
189	        if (points <= 1) {
190	            return 1;
191	        }
192	        if (points <= 3) {
193	            return 2;
194	        }
195	        if (points <= 5) {
196	            return 3;
197	        }
198	        return 4;
199	    }
200	
201	    /**
202	     * Derives the owner's locality (region) from the {@code customerCode}, whose form is
203	     * {@code '<REGION>-<HASH8>'}: the locality is the {@code REGION} segment before the first
204	     * hyphen. Returns {@code "UNKNOWN"} when the owner has no customer code yet.
205	     */
206	    default String locality(Owner owner) {
207	        if (owner == null) {
208	            return null;
209	        }
210	        String code = owner.getCustomerCode();
211	        if (code == null) {
212	            return "UNKNOWN";
213	        }
214	        int dash = code.indexOf('-');
215	        return dash >= 0 ? code.substring(0, dash) : code;
216	    }
217	
218	    /**
219	     * Derives the owner's IANA {@code timezone} from its locality/region using the fixed
220	     * region-to-timezone table ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
221	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region is not in the table.
222	     */
223	    default String timezone(Owner owner) {
224	        if (owner == null) {
225	            return null;
226	        }
227	        String region = locality(owner);
228	        return switch (region) {
229	            case "NSW" -> "Australia/Sydney";
230	            case "VIC" -> "Australia/Melbourne";
231	            case "QLD" -> "Australia/Brisbane";
232	            default -> null;
233	        };
234	    }
235	
236	    /**
