252	     * response.
253	     */
254	    default Boolean possibleDuplicate(Owner owner) {
255	        if (owner == null) {
256	            return null;
257	        }
258	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
259	    }
260	
261	    /**
262	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
263	     * present, otherwise {@code PHONE}.
264	     */
265	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
266	        if (owner == null) {
267	            return null;
268	        }
269	        String email = owner.getEmail();
270	        return (email != null && !email.isEmpty())
271	            ? OwnerDto.ContactPreferenceEnum.EMAIL
272	            : OwnerDto.ContactPreferenceEnum.PHONE;
273	    }
274	
