289	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
290	        if (owner == null || owner.getBirthDate() == null) {
291	            return null;
292	        }
293	        LocalDate reference = owner.getRegistrationDate();
294	        if (reference == null) {
295	            reference = LocalDate.now();
296	        }
297	        int age = Period.between(owner.getBirthDate(), reference).getYears();
298	        if (age < 18) {
299	            return OwnerDto.AgeBandEnum.MINOR;
300	        }
301	        if (age < 65) {
302	            return OwnerDto.AgeBandEnum.ADULT;
303	        }
304	        return OwnerDto.AgeBandEnum.SENIOR;
305	    }
