318	        ownerPageDto.setPage(ownerPage.getNumber());
319	        ownerPageDto.setSize(ownerPage.getSize());
320	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
321	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
322	        return ownerPageDto;
323	    }
